func extent_x(points: PackedVector3Array, keep: Callable) -> float:
	var lo := INF
	var hi := -INF
	for p in points:
		if keep.call(p):
			lo = minf(lo, p.x)
			hi = maxf(hi, p.x)
	return hi - lo if hi >= lo else 0.0

func box_gap(a: AABB, b: AABB) -> float:
	var gap := -INF
	for axis in range(3):
		gap = maxf(gap, maxf(a.position[axis] - b.end[axis], b.position[axis] - a.end[axis]))
	return gap

